#### CodeForce 1859A
https://vjudge.net/problem/CodeForces-1859A
```cpp
int main() {
	int rounds, length, input;
	cin >> rounds;
	multiset<int> nums;
	while(rounds) {
		cin >> length;
		for(int i = 0; i < length; i++) {
			cin >> input;
			nums.insert(input);
		}
		auto it			   = nums.rbegin();
		int	 biggest_count = nums.count(*it);
		if(length == biggest_count) {
			cout << -1 << '\n';
			rounds--;
			nums.clear();
			continue;
		}
		int i = 0;
		cout << nums.size() - biggest_count << ' ' << biggest_count << '\n';
		for(auto iterator = nums.begin(); i < nums.size() - biggest_count; i++, iterator++) {
			cout << *iterator << ' ';
		}
		cout << '\n';
		for(int i = 0; i < biggest_count; i++) {
			cout << *it << ' ';
		}
		cout << '\n';
		nums.clear();
		rounds--;
	}
}
```
数字，逻辑游戏
- 除数的定义是 y % x == 0，如果 x > y 且 y ≠ 0，那么 y % x == y ≠ 0，**所以 x 不可能是 y 的除数**
- 所以只要将数组中**最大的元素全部放在 C 中，B 中的元素永远不可能是 C 中元素的除数**
- 唯一一种特殊情况是所有数字都相等

